"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useCallback, useDeferredValue, useId, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useMotionValue } from "motion/react";

import { cn } from "../lib/cn";
import { useSyncRef } from "../hooks/use-latest";
import { duration } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty } from "./chart-parts";
import {
  DockHint,
  dockHintHeight,
  dockSpace,
  FittedTooltip,
  useDockedReadout,
  useInputSource,
  type Readout,
} from "./chart-fit";
import {
  chartFocusClass,
  chartKeyHandler,
  clamp,
  dataSignature,
  linear,
  num,
  rowKeys,
  thinLabels,
  useElementWidth,
  useHasMounted,
  ORIGIN_PT,
  resolveInstructions,
  itemAt,
} from "./chart-utils";
import { defaultCompact, defaultPercent, useEntrance } from "./heatmap";
import { solidTipsScope, useDeferredDraw } from "./category-bar";
import { ChartFigure } from "./chart-figure";
import { ChartPatternDefs, patternFill, resolvePatterns } from "./chart-patterns";

import {
  type Pt,
  type MorphTiming,
  useMorphClock,
  insideOutOrder,
  streamBaseline,
  defaultStreamgraphLabels,
  type StreamgraphProps,
  foldStreamSeries,
  CHAR_W,
  LABEL_CHAR_W,
  enterCurve,
  changeCurve,
  StreamLayer,
  layerColor,
} from "./streamgraph/model";

export {
  type Pt,
  monotoneTangents,
  curveSegments,
  bandArea,
  curvePath,
  SETTLED,
  type MorphTiming,
  useMorphPoints,
  useMorphClock,
  insideOutOrder,
  streamBaseline,
  type StreamgraphLabels,
  defaultStreamgraphLabels,
  type StreamgraphProps,
  foldStreamSeries,
  streamgraphLegend,
} from "./streamgraph/model";
export { type StreamgraphTableProps, StreamgraphTable } from "./streamgraph/parts";
/**
 * Stacked areas flowing around a moving centre line: how a mix of categories swells and fades
 * over time (genres, topics, traffic sources). Shape and share read at a glance; exact values
 * are one hover, tap or arrow key away.
 *
 * - Byron & Wattenberg's "wiggle" baseline and inside-out order keep the layers as flat and
 *   legible as possible; smooth monotone curves never overshoot a value.
 * - Each layer is named inside its thickest stretch when the name fits, on a small tag of the
 *   chart surface so the name reads on any layer colour.
 * - Hover a layer: it glows (dark theme) and the others step back; the crosshair reads every
 *   layer at that point, with its share of the total.
 * - Layers swell out of the centre line, inside out, the first time the chart scrolls into
 *   view; new data morphs them. Reduced motion: drawn in place.
 *
 * Keyboard: Tab focuses the chart; Left and Right move along the x axis, Up and Down walk the layers as they are stacked on screen, Home and End jump to the first and last x value, Escape clears.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; keyboard moves announce every layer's value at that point with its share of the total, and layer names are text on a chart-surface tag so they read on any colour. `StreamgraphTable` is the table view.
 * Glass and motion: the tooltip is a solid glass-look overlay (no backdrop blur). Reduced motion draws and morphs layers instantly.
 *
 * @example
 * ```tsx
 * import { Streamgraph } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <Streamgraph
 *       data={[
 *         { year: "2022", rock: 30, pop: 45, jazz: 12 },
 *         { year: "2023", rock: 25, pop: 52, jazz: 18 },
 *         { year: "2024", rock: 20, pop: 58, jazz: 22 },
 *       ]}
 *       index="year"
 *       series={[
 *         { key: "rock", label: "Rock" },
 *         { key: "pop", label: "Pop" },
 *         { key: "jazz", label: "Jazz" },
 *       ]}
 *       aria-label="Listening share by genre"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/streamgraph
 */
export function Streamgraph({
  data: dataProp,
  index,
  series: seriesProp,
  offset: offsetProp = "wiggle",
  order: orderProp = "insideOut",
  inlineLabels = true,
  height = 300,
  format: formatProp,
  formatPercent: pctProp,
  locale,
  emptyState,
  patterns,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<StreamgraphProps>) {
  const t = { ...defaultStreamgraphLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const pct = pctProp ?? defaultPercent(locale);
  const id = useId();
  const reduced = useSheenReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const play = useEntrance(rootRef, reduced);
  const docked = useDockedReadout(width);
  const [active, setActive] = useState<number | null>(null);
  const [layer, setLayer] = useState<number | null>(null);
  const { fromKeyboard, fromPointer, announce } = useInputSource();
  // New data or a new baseline is laid out in a deferred render (React yields while it rebuilds
  // the layers), so the control that changed it responds at once; then the layers morph.
  const data = useDeferredValue(dataProp);
  const series = useDeferredValue(seriesProp);
  const offset = useDeferredValue(offsetProp);
  const order = useDeferredValue(orderProp);
  // Marks are built once the chart nears the viewport, in a deferred render (see useDeferredDraw):
  // a page load or a ChartCard's Chart tab coming back paints the frame at once, the marks right after.
  const drawn = useDeferredDraw(rootRef);

  const { rows, series: layers } = useMemo(() => foldStreamSeries(data, series, t.other), [data, series, t.other]);
  const hatched = resolvePatterns(patterns, layers.length);
  const count = rows.length;
  const values = useMemo(() => layers.map((s) => rows.map((row) => Math.max(0, num(row[s.key])))), [layers, rows]);
  const stackOrder = useMemo(
    () => (order === "insideOut" ? insideOutOrder(values) : values.map((_, i) => i)),
    [values, order],
  );
  const totals = useMemo(() => rows.map((_, j) => values.reduce((s, v) => s + (v[j] ?? 0), 0)), [rows, values]);
  const isEmpty = count === 0 || layers.length === 0 || totals.every((v) => v === 0);

  const keys = useMemo(() => rowKeys(rows, index), [rows, index]);
  const version = keys.join("\u0001") + "|" + stackOrder.join(",");
  const signature = dataSignature(rows, [index, ...layers.map((s) => s.key)]) + offset + order;
  const mounted = useHasMounted(width > 0 && !isEmpty && play);

  // Per x: the layers by value (largest first), then the total. `order` keeps which layer each row is.
  const readouts = useMemo(
    () =>
      rows.map((row, j) => {
        const byValue = layers.map((s, si) => ({ s, si, v: values[si]?.[j] ?? 0 })).sort((a, b) => b.v - a.v);
        return {
          title: String(row[index] ?? ""),
          order: byValue.map((r) => r.si),
          rows: [
            ...byValue.map(({ s, si, v }) => ({
              label: `${s.label} · ${pct(totals[j] ? v / totals[j] : NaN)}`,
              value: format(v),
              color: layerColor(s, si),
              kind: "rect" as const,
            })),
            { label: t.total, value: format(totals[j] ?? 0), color: "transparent" },
          ],
        } satisfies Readout & { order: number[] };
      }),
    [rows, layers, values, totals, index, format, pct, t.total],
  );
  const dock = docked ? dockSpace(width, readouts, 3) : 0;

  const M = { top: 8 + dock, bottom: 28, left: 8, right: 8 };
  const innerW = Math.max(0, width - M.left - M.right);
  const innerH = Math.max(0, height - M.top - M.bottom);
  const x = useCallback((j: number) => (count <= 1 ? innerW / 2 : (j / (count - 1)) * innerW), [count, innerW]);

  // Layer edges in value space, bottom layer first.
  const geometry = useMemo(() => {
    const ordered = stackOrder.map((i) => values[i] ?? []);
    const base = streamBaseline(ordered, offset);
    const edges: { lo: number[]; hi: number[] }[] = [];
    const run = base.slice();
    for (const v of ordered) {
      const lo = run.slice();
      const hi = run.map((b, j) => b + (v[j] ?? 0));
      edges.push({ lo, hi });
      for (let j = 0; j < run.length; j++) run[j] = hi[j] ?? 0;
    }
    let min = Infinity;
    let max = -Infinity;
    for (const e of edges)
      for (let j = 0; j < count; j++) {
        min = Math.min(min, e.lo[j] ?? 0);
        max = Math.max(max, e.hi[j] ?? 0);
      }
    return { edges, base, min: Number.isFinite(min) ? min : 0, max: Number.isFinite(max) ? max : 1 };
  }, [values, stackOrder, offset, count]);

  // Layer paths and inline names depend on the data and the size only, never on what is being
  // read: built once per layout, so hovering re-renders no curves.
  const { paths, names } = useMemo(() => {
    const pad = (geometry.max - geometry.min) * 0.04 || 1;
    const y = linear(geometry.min - pad, geometry.max + pad, innerH, 0);

    const paths = stackOrder.map((si, p) => {
      const e = itemAt(geometry.edges, p);
      const top: Pt[] = e.hi.map((v, j) => [x(j), y(v)]);
      const bottom: Pt[] = e.lo.map((v, j) => [x(j), y(v)]);
      const mid: Pt[] = e.lo.map((v, j) => [x(j), y((v + (e.hi[j] ?? 0)) / 2)]);
      const s = itemAt(layers, si);
      return { si, s, color: layerColor(s, si), top, bottom, mid };
    });

    // Inline names: at the thickest x of each layer where the name's tag fits inside it (trying
    // the next thickest when it doesn't), so even a layer with one cramped peak gets its name.
    const names = inlineLabels
      ? paths.map((p) => {
          const w = p.s.label.length * CHAR_W + 18;
          // The name's tag (its width, 20px tall around the layer's middle there) must stay inside
          // the layer all along, with a little air: check its edges at five points across.
          const edgesAt = (px: number) => {
            const k = count <= 1 ? 0 : clamp((px / Math.max(1, innerW)) * (count - 1), 0, count - 1);
            const a = Math.floor(k);
            const b = Math.min(count - 1, a + 1);
            const tt = k - a;
            return {
              top: (p.top[a] ?? ORIGIN_PT)[1] * (1 - tt) + (p.top[b] ?? ORIGIN_PT)[1] * tt,
              bot: (p.bottom[a] ?? ORIGIN_PT)[1] * (1 - tt) + (p.bottom[b] ?? ORIGIN_PT)[1] * tt,
            };
          };
          const candidates: { j: number; th: number }[] = [];
          for (let j = 0; j < count; j++) {
            const th = (p.bottom[j] ?? ORIGIN_PT)[1] - (p.top[j] ?? ORIGIN_PT)[1];
            const cx = x(j);
            if (th >= 26 && cx - w / 2 >= 0 && cx + w / 2 <= innerW) candidates.push({ j, th });
          }
          candidates.sort((a, b) => b.th - a.th);
          for (const { j } of candidates.slice(0, 12)) {
            const cx = x(j);
            const centre = edgesAt(cx);
            const cy = (centre.top + centre.bot) / 2;
            const fits = [-0.5, -0.25, 0, 0.25, 0.5].every((f) => {
              const e = edgesAt(cx + f * w);
              return e.top <= cy - 12 && e.bot >= cy + 12;
            });
            if (fits) return { x: cx, y: cy, w, text: p.s.label };
          }
          return null;
        })
      : [];
    return { paths, names };
  }, [geometry, stackOrder, layers, innerW, innerH, count, inlineLabels, x]);

  // Choreography on one clock: layers swell out of their centre lines, inside out; data changes
  // morph them. Resizes snap; reduced motion draws in place.
  const clock = useMotionValue(0);
  const centre = (layers.length - 1) / 2;
  const centreRef = useRef(centre);
  useSyncRef(centreRef, centre);
  const phase = useMorphClock(clock, {
    play,
    ready: width > 0 && !isEmpty && drawn,
    reduced,
    signature,
    version: paths,
    entrance: duration.slower * 1.3 + centre * 0.07,
    change: duration.slow,
  });
  const [timing] = useState(
    () =>
      (order: number): MorphTiming =>
        phase.current === "enter"
          ? { delay: Math.abs(order - centreRef.current) * 0.07, span: duration.slower * 1.3, ease: enterCurve }
          : { delay: 0, span: duration.slow, ease: changeCurve },
  );

  if (isEmpty) {
    return (
      <div ref={measureRef} className={cn("w-full", className)}>
        <ChartEmpty height={height} aria-label={ariaLabel}>
          {emptyState ?? t.empty}
        </ChartEmpty>
      </div>
    );
  }

  const act = active !== null && active < count ? active : null;
  const focusLayer = layer !== null && layer < layers.length ? layer : null;
  const readout = act !== null ? readouts[act] : undefined;
  const focusName = focusLayer !== null ? itemAt(layers, focusLayer).label : null;
  const announceText = (() => {
    if (!readout || act === null) return focusLayer !== null && focusName ? focusName : "";
    if (focusLayer !== null && focusName) {
      const v = values[focusLayer]?.[act] ?? 0;
      return `${readout.title}, ${focusName}: ${format(v)}, ${pct(totals[act] ? v / totals[act] : NaN)}`;
    }
    const total = totals[act] ?? 0;
    const parts = readout.order.map((si) => {
      const v = values[si]?.[act] ?? 0;
      return `${itemAt(layers, si).label} ${format(v)} (${pct(total ? v / total : NaN)})`;
    });
    return `${readout.title}: ${parts.join(", ")}. ${t.total} ${format(total)}`;
  })();

  const xLabels = rows.map((row) => String(row[index] ?? ""));
  const shownLabels = thinLabels(xLabels, count > 1 ? innerW / (count - 1) : innerW);
  // Labels stay inside the plot: centred on their x, but slid in where that would cross an edge
  // (the first and last labels sit flush with the ends in every browser).
  const labelBox = (j: number) => {
    const w = (xLabels[j]?.length ?? 0) * LABEL_CHAR_W;
    const cx = x(j);
    if (cx - w / 2 < 0) return { x: Math.max(cx - w / 2, -M.left + 2), anchor: "start" as const };
    if (cx + w / 2 > innerW) return { x: Math.min(cx + w / 2, innerW + M.right - 2), anchor: "end" as const };
    return { x: cx, anchor: "middle" as const };
  };

  function onPointer(event: React.PointerEvent<SVGRectElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    fromPointer();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;
    const j = count <= 1 ? 0 : clamp(Math.round((px / Math.max(1, rect.width)) * (count - 1)), 0, count - 1);
    setActive(j);
    // Which layer is under the pointer (between its edges at this x)?
    const k = count <= 1 ? 0 : clamp((px / Math.max(1, rect.width)) * (count - 1), 0, count - 1);
    const a = Math.floor(k);
    const b = Math.min(count - 1, a + 1);
    const tt = k - a;
    const hit = paths.find((p) => {
      const top = (p.top[a] ?? ORIGIN_PT)[1] * (1 - tt) + (p.top[b] ?? ORIGIN_PT)[1] * tt;
      const bot = (p.bottom[a] ?? ORIGIN_PT)[1] * (1 - tt) + (p.bottom[b] ?? ORIGIN_PT)[1] * tt;
      return py >= top && py <= bot;
    });
    setLayer(hit ? hit.si : null);
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    fromKeyboard();
    if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      e.preventDefault();
      // Up and down walk the layers as stacked on screen (top layer first).
      const onScreen = [...stackOrder].reverse();
      const at = focusLayer === null ? -1 : onScreen.indexOf(focusLayer);
      const next = e.key === "ArrowDown" ? Math.min(onScreen.length - 1, at + 1) : Math.max(0, at <= 0 ? 0 : at - 1);
      setLayer(onScreen[next] ?? null);
      if (act === null) setActive(count - 1);
      return;
    }
    if (e.key === "Escape") setLayer(null);
    chartKeyHandler(count, act, setActive)(e);
  };

  return (
    <div {...rest} ref={rootMerged} className={cn("relative w-full", className)}>
      <div ref={measureRef} className={cn("relative w-full", solidTipsScope)} style={{ height }}>
        {width > 0 && (
          <ChartFigure
            as="svg"
            width={width}
            height={height}
            label={ariaLabel}
            description={resolveInstructions(t.instructions)}
            tabIndex={0}
            onKeyDown={onKeyDown}
            onBlur={() => {
              setActive(null);
              setLayer(null);
            }}
            className={cn("overflow-visible rounded-sheen-sm", chartFocusClass)}
            // Time runs left to right in every locale; horizontal drags scrub (vertical swipes scroll).
            style={{ direction: "ltr", touchAction: "pan-y pinch-zoom" }}
          >
            <defs>
              {/* A soft sheen across every layer: lighter at the crest, the pure hue below. */}
              <linearGradient id={`${id}-sheen`} x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" style={{ stopColor: "var(--sheen-ink-0)" }} stopOpacity={0.16} />
                <stop offset="0.55" style={{ stopColor: "var(--sheen-ink-0)" }} stopOpacity={0} />
              </linearGradient>
              <clipPath id={`${id}-clip`}>
                <rect x={-2} y={-2} width={innerW + 4} height={innerH + 4} />
              </clipPath>
            </defs>
            {hatched && (
              <ChartPatternDefs id={id} entries={layers.map((s, i) => ({ index: i, color: layerColor(s, i) }))} />
            )}
            <g aria-hidden transform={`translate(${M.left},${M.top})`}>
              {/* Centre line (silhouette) or a faint baseline for orientation. */}
              <line x1={0} x2={innerW} y1={innerH + 6} y2={innerH + 6} stroke="var(--sheen-chart-grid)" />

              <g clipPath={`url(#${id}-clip)`} className="forced-color-adjust-none">
                <AnimatePresence>
                  {drawn &&
                    paths.map((p, pi) => (
                      <StreamLayer
                        key={`${p.s.key}-${version}`}
                        top={p.top}
                        bottom={p.bottom}
                        mid={p.mid}
                        clock={clock}
                        timing={timing}
                        order={pi}
                        color={p.color}
                        fill={patternFill(hatched, id, p.si, p.color)}
                        sheen={`url(#${id}-sheen)`}
                        stroke={layers.length > 1 ? 2 : 0}
                        lit={focusLayer === p.si}
                        dim={focusLayer !== null && focusLayer !== p.si}
                        reduced={reduced}
                      />
                    ))}
                </AnimatePresence>
              </g>

              {/* Inline names on small frosted tags: ink text on the chart surface, so they read
                  (AA) on every layer colour in both themes, never text in a series colour. */}
              {names.map((nm, i) =>
                nm && drawn ? (
                  <motion.g
                    key={`${itemAt(paths, i).s.key}-${version}`}
                    className="pointer-events-none"
                    initial={reduced ? false : { opacity: 0 }}
                    animate={{ opacity: focusLayer !== null && focusLayer !== itemAt(paths, i).si ? 0 : 1 }}
                    transition={{
                      duration: reduced ? 0 : duration.base,
                      delay: mounted || reduced ? 0 : duration.slower,
                    }}
                  >
                    <rect
                      x={nm.x - nm.w / 2}
                      y={nm.y - 10}
                      width={nm.w}
                      height={20}
                      rx={10}
                      fill="var(--sheen-chart-surface)"
                      fillOpacity={0.86}
                      className="forced-colors:fill-[Canvas] forced-colors:stroke-[CanvasText]"
                    />
                    <text
                      x={nm.x}
                      y={nm.y}
                      dy="0.35em"
                      textAnchor="middle"
                      className="fill-sheen-fg text-xs font-medium forced-colors:fill-[CanvasText]"
                    >
                      {nm.text}
                    </text>
                  </motion.g>
                ) : null,
              )}

              {xLabels.map((label, j) => {
                if (!shownLabels.has(j)) return null;
                const box = labelBox(j);
                return (
                  <text
                    key={keys[j]}
                    x={box.x}
                    y={innerH + 22}
                    textAnchor={box.anchor}
                    className="fill-sheen-fg-muted text-2xs"
                  >
                    {label}
                  </text>
                );
              })}

              {/* Crosshair: a hairline and a ringed dot in the middle of each layer. */}
              {act !== null && (
                <g pointerEvents="none">
                  <line x1={x(act)} x2={x(act)} y1={0} y2={innerH} stroke="var(--sheen-fg-subtle)" />
                  <g className="forced-color-adjust-none">
                    {paths.map((p) => {
                      const th = (p.bottom[act] ?? ORIGIN_PT)[1] - (p.top[act] ?? ORIGIN_PT)[1];
                      if (th < 3) return null;
                      return (
                        <circle
                          key={p.si}
                          cx={x(act)}
                          cy={((p.top[act] ?? ORIGIN_PT)[1] + (p.bottom[act] ?? ORIGIN_PT)[1]) / 2}
                          r={focusLayer === p.si ? 5 : 4}
                          fill={p.color}
                          stroke="var(--sheen-chart-surface)"
                          strokeWidth={2}
                        />
                      );
                    })}
                  </g>
                </g>
              )}

              <rect
                width={innerW}
                height={innerH}
                fill="transparent"
                onPointerDown={onPointer}
                onPointerMove={onPointer}
                onPointerLeave={(e) => {
                  if (e.pointerType !== "mouse") return;
                  setActive(null);
                  setLayer(null);
                }}
              />
            </g>
          </ChartFigure>
        )}

        {docked && act === null && <DockHint height={dockHintHeight(dock)}>{t.touchHint}</DockHint>}
        {readout && act !== null && (
          <FittedTooltip
            title={readout.title}
            rows={(() => {
              // The layer under the pointer (or picked with up / down) leads the list.
              const at = focusLayer === null ? -1 : readout.order.indexOf(focusLayer);
              return at <= 0 ? readout.rows : [itemAt(readout.rows, at), ...readout.rows.filter((_, i) => i !== at)];
            })()}
            x={M.left + x(act)}
            y={M.top + innerH / 2}
            containerWidth={width}
            docked={docked}
          />
        )}
      </div>
      <ChartAnnouncer text={announce(announceText)} />
    </div>
  );
}

"use client";

import { memo, useLayoutEffect, useMemo, useRef, type ReactNode } from "react";
import { animate, cubicBezier, motion, useMotionValue, useTransform, type MotionValue } from "motion/react";

import { useSyncRef } from "../../hooks/use-latest";
import { duration } from "../../motion/tokens";
import { type LegendItem } from "../chart-parts";
import { resolvePatterns } from "../chart-patterns";
import {
  changeEase,
  clamp,
  enterEase,
  exitTransition,
  MAX_SERIES,
  num,
  seriesColor,
  slotColor,
  type ChartRow,
  type ChartSeries,
  ORIGIN_PT,
  type ChartInstructions,
  monotoneTangents,
  type Pt,
} from "../chart-utils";
import { markGlow } from "../category-bar";

/* ======================================================================
 * Curves (shared with the ridgeline chart)
 * ====================================================================== */

/** @internal A point in px. */
export type { Pt };
export { monotoneTangents };
/** Formats a number to one decimal for path data, mapping non-finite values to 0. @internal */
export const f = (n: number) => (Number.isFinite(n) ? n.toFixed(1) : "0");

/**
 * @internal Cubic segments through the points (no initial move): one per neighbouring pair, so
 * two curves over the same xs share a command structure and Motion can morph between them.
 * `reverse` walks the same curve backwards (for closing an area along its lower edge).
 */
export function curveSegments(pts: readonly Pt[], reverse = false) {
  if (pts.length < 2) return "";
  const t = monotoneTangents(pts);
  const parts: string[] = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const [x0, y0] = pts[i] ?? ORIGIN_PT;
    const [x1, y1] = pts[i + 1] ?? ORIGIN_PT;
    const dx = (x1 - x0) / 3;
    const c1: Pt = [x0 + dx, y0 + dx * (t[i] ?? 0)];
    const c2: Pt = [x1 - dx, y1 - dx * (t[i + 1] ?? 0)];
    parts.push(
      reverse
        ? `C${f(c2[0])},${f(c2[1])} ${f(c1[0])},${f(c1[1])} ${f(x0)},${f(y0)}`
        : `C${f(c1[0])},${f(c1[1])} ${f(c2[0])},${f(c2[1])} ${f(x1)},${f(y1)}`,
    );
  }
  return (reverse ? parts.reverse() : parts).join(" ");
}

/** @internal A closed area between an upper and a lower edge over the same xs. One point: a thin sliver. */
export function bandArea(top: readonly Pt[], bottom: readonly Pt[]) {
  const first = top[0];
  const last = bottom[bottom.length - 1];
  if (!first || !last) return "";
  if (top.length === 1) {
    const b = bottom[0] ?? ORIGIN_PT;
    return `M${f(first[0] - 6)},${f(first[1])} L${f(first[0] + 6)},${f(first[1])} L${f(b[0] + 6)},${f(b[1])} L${f(b[0] - 6)},${f(b[1])} Z`;
  }
  return `M${f(first[0])},${f(first[1])} ${curveSegments(top)} L${f(last[0])},${f(last[1])} ${curveSegments(bottom, true)} Z`;
}

/** @internal An open curve through the points. */
export function curvePath(pts: readonly Pt[]) {
  const first = pts[0];
  return first ? `M${f(first[0])},${f(first[1])} ${curveSegments(pts)}` : "";
}

/* ======================================================================
 * Morphs on one clock (shared with the ridgeline chart)
 * ====================================================================== */

/** @internal A clock value past every tween: shapes are drawn at their targets. */
export const SETTLED = 1e9;

/** @internal When a shape's tween starts on the clock (s), how long it takes (s), and its easing. */
export type MorphTiming = { delay: number; span: number; ease: (k: number) => number };

/**
 * @internal Points that tween from what is drawn now to `target` on a shared `clock` MotionValue
 * (seconds since the current tween started; SETTLED when idle). `enter` is where a new shape
 * starts (a flat or centre line). Path strings are built from the points in useTransform, so a
 * morph never re-renders React and Motion never has to parse or mix path strings: one clock
 * drives every shape of the chart. `timing` is read on every frame (it may change between the
 * entrance and later updates).
 *
 * Arguments: `target` (the points to reach), `enter` (where a new shape starts, e.g. a flat line), `clock` (a MotionValue in seconds, SETTLED when idle) and `timing()` ({ delay, span, ease } of this shape's tween). Returns a MotionValue of the points currently drawn; build the path string from it with `useTransform`. Not a component: no DOM, keyboard or screen-reader behaviour. With reduced motion the clock is set to SETTLED, so shapes sit at their targets.
 *
 * @example
 * ```tsx
 * import { useMotionValue } from "motion/react";
 * import { SETTLED, useMorphClock, useMorphPoints, type Pt } from "./model";
 *
 * function Shape({ target, play, reduced, version }: { target: Pt[]; play: boolean; reduced: boolean; version: string }) {
 *   const clock = useMotionValue(SETTLED);
 *   const flat: Pt[] = target.map(([x]) => [x, 0]);
 *   const points = useMorphPoints(target, flat, clock, () => ({ delay: 0, span: 0.6, ease: (k) => k }));
 *   useMorphClock(clock, { play, ready: true, reduced, signature: "", version, entrance: 0.8, change: 0.5 });
 *   return <p>{points.get().length} points</p>;
 * }
 * ```
 *
 * @see /charts/streamgraph
 */
export function useMorphPoints(
  target: readonly Pt[],
  enter: readonly Pt[],
  clock: MotionValue<number>,
  timing: () => MorphTiming,
) {
  const state = useRef<{ from: readonly Pt[]; to: readonly Pt[]; drawn: readonly Pt[] }>({
    from: enter,
    to: target,
    drawn: enter,
  });
  // Bumped when a new target is adopted, so a shape redraws even when the clock does not move (a resize, or reduced motion).
  const adopted = useMotionValue(0);
  // A new target: the tween starts from what is drawn now. Done in a layout effect, before the chart's clock (declared after the shapes) starts.
  useLayoutEffect(() => {
    if (state.current.to === target) return;
    state.current = { from: state.current.drawn, to: target, drawn: state.current.drawn };
    adopted.set(adopted.get() + 1);
  }, [target, adopted]);
  const timingRef = useRef(timing);
  useSyncRef(timingRef, timing);
  return useTransform([clock, adopted], ([c = 0]: number[]) => {
    const s = state.current;
    const { delay, span, ease } = timingRef.current();
    const k = span <= 0 ? 1 : clamp((c - delay) / span, 0, 1);
    const pts = k >= 1 ? s.to : k <= 0 ? s.from : lerpPoints(s.from, s.to, ease(k));
    s.drawn = pts;
    return pts;
  });
}

/** Points part-way from `a` to `b` (any lengths: missing ones start from the nearest end). */
export function lerpPoints(a: readonly Pt[], b: readonly Pt[], k: number): Pt[] {
  return b.map(([bx, by], i) => {
    const [ax, ay] = a[i] ?? a[a.length - 1] ?? [bx, by];
    return [ax + (bx - ax) * k, ay + (by - ay) * k] as const;
  });
}

/**
 * @internal Runs a chart's clock: the entrance once it plays, a tween on every data change, and
 * a snap (no animation) on resizes or under reduced motion. Call after the shapes' hooks.
 *
 * Arguments: the shared `clock` and `{ play, ready, reduced, signature, version, entrance, change }`: start when `play` and `ready` are true, `signature` is a string that changes with the data (a resize leaves it alone), `version` changes with the drawn shapes, and `entrance` / `change` are the tween lengths in seconds. Returns a ref holding the running phase ("enter" or "change"). Not a component: no DOM, keyboard or screen-reader behaviour. Under reduced motion, or on a resize, the clock jumps to SETTLED.
 *
 * @example
 * ```tsx
 * import { useMotionValue } from "motion/react";
 * import { SETTLED, useMorphClock } from "./model";
 *
 * function Clock({ play, reduced, version }: { play: boolean; reduced: boolean; version: string }) {
 *   const clock = useMotionValue(SETTLED);
 *   const phase = useMorphClock(clock, { play, ready: true, reduced, signature: "", version, entrance: 0.8, change: 0.5 });
 *   return <p>{phase.current}</p>;
 * }
 * ```
 *
 * @see /charts/streamgraph
 */
export function useMorphClock(
  clock: MotionValue<number>,
  {
    play,
    ready,
    reduced,
    signature,
    version,
    entrance,
    change,
  }: {
    play: boolean;
    ready: boolean;
    reduced: boolean;
    /** A cheap string that changes when the data does (a resize leaves it alone). */
    signature: string;
    /** Anything that changes the drawn shapes (data, layout). */
    version: unknown;
    /** Total length of the entrance and of a data-change tween, in seconds. */
    entrance: number;
    change: number;
  },
) {
  const entered = useRef(false);
  const lastSignature = useRef(signature);
  /** Which tween the clock is running: shapes pick their delay and length from it. */
  const phase = useRef<"enter" | "change">("enter");
  useLayoutEffect(() => {
    // The data changed since the last run (a resize is not a change).
    const changed = lastSignature.current !== signature;
    lastSignature.current = signature;
    if (!play || !ready) return;
    if (reduced || (entered.current && !changed)) {
      entered.current = true;
      clock.jump(SETTLED);
      return;
    }
    phase.current = entered.current ? "change" : "enter";
    const total = entered.current ? change : entrance;
    entered.current = true;
    clock.jump(0);
    const controls = animate(clock, total, { duration: total, ease: "linear" });
    return () => controls.stop();
  }, [play, ready, reduced, version, signature, clock, entrance, change]);
  return phase;
}

/* ======================================================================
 * Stack layout
 * ====================================================================== */

/**
 * Inside-out order (Byron & Wattenberg): series that peak early and late go to the edges, the
 * ones peaking mid-way sit in the middle, balancing the two sides by total. Returns series
 * indices from the bottom layer up.
 *
 * @see /charts/streamgraph
 */
export function insideOutOrder(values: number[][]) {
  const peaks = values.map((v) => v.reduce((best, x, i) => (x > (v[best] ?? -Infinity) ? i : best), 0));
  const sums = values.map((v) => v.reduce((s, x) => s + x, 0));
  const byPeak = values.map((_, i) => i).sort((a, b) => (peaks[a] ?? 0) - (peaks[b] ?? 0) || a - b);
  let top = 0;
  let bottom = 0;
  const tops: number[] = [];
  const bottoms: number[] = [];
  for (const i of byPeak) {
    if (top < bottom) {
      top += sums[i] ?? 0;
      tops.push(i);
    } else {
      bottom += sums[i] ?? 0;
      bottoms.push(i);
    }
  }
  return [...bottoms.reverse(), ...tops];
}

/**
 * Baseline per x of a stream: "wiggle" minimises the layers' weighted slope (Byron &
 * Wattenberg's streamgraph, as d3's stackOffsetWiggle); "silhouette" centres the stack on zero.
 * `values` are in stacking order.
 *
 * @see /charts/streamgraph
 */
export function streamBaseline(values: number[][], offset: "wiggle" | "silhouette") {
  const m = values[0]?.length ?? 0;
  const total = (j: number) => values.reduce((s, v) => s + (v[j] ?? 0), 0);
  if (offset === "silhouette") return Array.from({ length: m }, (_, j) => -total(j) / 2);
  const g = new Array<number>(m).fill(0);
  for (let j = 1; j < m; j++) {
    let s1 = 0;
    let s2 = 0;
    let below = 0;
    for (const v of values) {
      const now = v[j] ?? 0;
      const dv = now - (v[j - 1] ?? 0);
      s1 += now;
      s2 += now * (below + dv / 2);
      below += dv;
    }
    g[j] = (g[j - 1] ?? 0) - (s1 ? s2 / s1 : 0);
  }
  // Centre the whole stream on zero, so its drift doesn't decide the axis.
  const mid = g.reduce((s, b, j) => s + b + total(j) / 2, 0) / Math.max(1, m);
  return g.map((b) => b - mid);
}

/* ======================================================================
 * Streamgraph
 * ====================================================================== */

/**
 * Every string Streamgraph speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type StreamgraphLabels = {
  instructions: ChartInstructions;
  /** Tooltip row for the sum of every layer. */
  total: string;
  /** Name of the layer that folds everything past the 8th series. */
  other: string;
  /** Touch screens: the hint in the readout band before anything is read. */
  touchHint: string;
  empty: string;
};

/**
 * The built-in English strings of Streamgraph; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultStreamgraphLabels: StreamgraphLabels = {
  instructions: "Use left and right arrow keys to move through time, up and down to pick a layer.",
  total: "Total",
  other: "Other",
  touchHint: "Tap or drag across the chart to read values",
  empty: "No data",
};

/**
 * Props of Streamgraph. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type StreamgraphProps = {
  /** One row per x value (e.g. per week). */
  data: readonly ChartRow[];
  /** Key of the x value in each row. */
  index: string;
  /** The layers. Up to 8 keep their colour slot; any more fold into “Other”. */
  series: readonly ChartSeries[];
  /** "wiggle" (default): the classic streamgraph, as flat as possible. "silhouette": mirrored around a centre line. */
  offset?: "wiggle" | "silhouette";
  /** "insideOut" (default) puts layers that peak mid-way in the middle; "none" keeps `series` order (bottom up). */
  order?: "insideOut" | "none";
  /** Name each layer inside its thickest stretch, when it fits. Default true. */
  inlineLabels?: boolean;
  /** Height of the chart in px; the width follows the container. Default 300. */
  height?: number;
  /** Formats a value for the tooltips and data table: takes the number, returns the text shown. Default: formatCompact in `locale`. */
  format?: (n: number) => string;
  /** Formats shares of the total. Default: percentages in `locale`. */
  formatPercent?: (ratio: number) => string;
  /** Locale of the default number formats. Default "en". */
  locale?: string;
  /** Shown when there is nothing to plot. */
  emptyState?: ReactNode;
  /**
   * Tell layers apart without colour (hatch fills; the first layer stays solid). Default: on when the chart has more
   * than 3 layers.
   *
   * @default true when layers > 3
   */
  patterns?: boolean;
  /** Override the chart's strings (i18n). */
  labels?: Partial<StreamgraphLabels>;
  /** Accessible summary of what the chart shows. */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** The key of the folded other layer. @internal */
export const OTHER = "__other";
/** The average glyph width of the inline layer labels, in pixels. @internal */
export const CHAR_W = 6.8; // average glyph width of the 12px medium inline labels
/** The average glyph width of the x-axis labels, in pixels. @internal */
export const LABEL_CHAR_W = 6.2; // the 11px x-axis labels

/** Builds an easing function from four cubic-bezier numbers. @internal */
export const bezier = (e: readonly number[]) => cubicBezier(e[0] ?? 0, e[1] ?? 0, e[2] ?? 1, e[3] ?? 1);
/** The enter easing as a function. @internal */
export const enterCurve = bezier(enterEase);
/** The data-change easing as a function. @internal */
export const changeCurve = bezier(changeEase);

/**
 * One layer of the stream and its sheen. Both follow one morphing outline (top edge, then the
 * bottom edge), so a data change or the entrance never re-renders React per frame. The shape is
 * memoised apart from its emphasis: hovering another layer only flips data attributes on this
 * group (CSS dims the sheen and lights the glow), so no path is rebuilt on a hover.
 */
export const StreamLayer = memo(function StreamLayer({
  lit,
  dim,
  reduced,
  ...shape
}: StreamShapeProps & { lit: boolean; dim: boolean; reduced: boolean }) {
  return (
    <motion.g
      data-layer-lit={lit ? "" : undefined}
      data-layer-dim={dim ? "" : undefined}
      initial={{ opacity: 1 }}
      animate={{ opacity: dim ? 0.32 : 1 }}
      exit={{ opacity: 0, transition: reduced ? { duration: 0 } : exitTransition }}
      transition={{ opacity: { duration: reduced ? 0 : duration.fast } }}
    >
      <StreamShape {...shape} />
    </motion.g>
  );
});

/** The props of one stream layer shape. @internal */
export type StreamShapeProps = {
  top: readonly Pt[];
  bottom: readonly Pt[];
  mid: readonly Pt[];
  clock: MotionValue<number>;
  /** Timing of the layer at `order` (stable function; reads the chart's current phase). */
  timing: (order: number) => MorphTiming;
  order: number;
  color: string;
  /** Fill of the layer itself (a hatch pattern url); `color` when unset. */
  fill?: string;
  /** Fill of the sheen over the layer. */
  sheen: string;
  stroke: number;
};

/** One stream layer, drawn as an animated path. @internal */
export const StreamShape = memo(function StreamShape({
  top,
  bottom,
  mid,
  clock,
  timing,
  order,
  color,
  fill,
  sheen,
  stroke,
}: StreamShapeProps) {
  const target = useMemo(() => [...top, ...bottom], [top, bottom]);
  const enter = useMemo(() => [...mid, ...mid], [mid]);
  const pts = useMorphPoints(target, enter, clock, () => timing(order));
  const d = useTransform(pts, (p: readonly Pt[]) => {
    const half = p.length / 2;
    return bandArea(p.slice(0, half), p.slice(half));
  });
  return (
    <>
      <motion.path
        d={d}
        fill={fill ?? color}
        stroke="var(--sheen-chart-surface)"
        strokeWidth={stroke}
        strokeLinejoin="round"
        className="forced-colors:stroke-[CanvasText] in-data-layer-lit:[filter:var(--layer-glow)]"
        style={{ "--layer-glow": markGlow(color, 7) } as React.CSSProperties}
      />
      {/* The sheen sits over the layer as its own shape, so it never changes the colour key. */}
      <motion.path
        d={d}
        pointerEvents="none"
        fill={sheen}
        className="forced-colors:hidden in-data-layer-dim:opacity-0 motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
      />
    </>
  );
});

/** Fold series past the 8th into one "Other" layer (neutral grey). Returns rows with its value added.
 *
 * @see /charts/streamgraph
 */
export function foldStreamSeries(
  data: readonly ChartRow[],
  series: readonly ChartSeries[],
  otherLabel = defaultStreamgraphLabels.other,
) {
  if (series.length <= MAX_SERIES) return { rows: data, series };
  const kept = series
    .slice(0, MAX_SERIES - 1)
    .map((s, i) => ({ ...s, color: s.color ?? ((i + 1) as ChartSeries["color"]) }));
  const rest = series.slice(MAX_SERIES - 1);
  const rows: ChartRow[] = data.map((row) => ({
    ...row,
    [OTHER]: rest.reduce((sum, s) => sum + Math.max(0, num(row[s.key])), 0),
  }));
  return { rows, series: [...kept, { key: OTHER, label: otherLabel }] };
}

/** The colour of a layer, with the other layer in the neutral slot. @internal */
export const layerColor = (s: ChartSeries, i: number) => (s.key === OTHER ? slotColor(0) : seriesColor(s, i));

/** Legend for a streamgraph: one swatch per layer, as folded.
 *
 * @see /charts/streamgraph
 */
export function streamgraphLegend(
  series: readonly ChartSeries[],
  otherLabel?: string,
  /** Hatch the swatches like the chart's `patterns` prop. Default: on from 4 layers, as in the chart. */
  patterns?: boolean,
): LegendItem[] {
  const layers = foldStreamSeries([], series, otherLabel).series;
  const hatched = resolvePatterns(patterns, layers.length);
  return layers.map((s, i) => ({
    label: s.label,
    color: layerColor(s, i),
    kind: "rect",
    pattern: hatched && i > 0 ? i : undefined,
  }));
}

"use client";

import { useMemo } from "react";

import { SeriesTable } from "../chart-fit";
import { defaultCompact } from "../heatmap";
import { useTableRows } from "../category-bar";
import { defaultStreamgraphLabels, type StreamgraphProps, foldStreamSeries, layerColor } from "./model";

/* ---------- Table view ---------- */

/**
 * Props of StreamgraphTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type StreamgraphTableProps = Pick<
  StreamgraphProps,
  "data" | "index" | "series" | "format" | "locale" | "labels"
> & {
  /** Sets the header of the first column. */
  indexLabel?: string;
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
};

/**
 * One row per x value, one column per layer, plus the total.
 *
 * Props: the chart's `data`, `index`, `series`, `format`, `locale` and `labels`, plus `indexLabel` (first column header) and `caption` (hidden, names the table). A real table: one row per x value, one column per layer, plus the total. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { StreamgraphTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <StreamgraphTable
 *       data={[{ year: "2022", rock: 30, pop: 45 }]}
 *       index="year"
 *       series={[
 *         { key: "rock", label: "Rock" },
 *         { key: "pop", label: "Pop" },
 *       ]}
 *       indexLabel="Year"
 *       caption="Listening share by genre"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/streamgraph
 */
export function StreamgraphTable({
  data,
  index,
  series,
  format: formatProp,
  locale,
  labels: labelOverrides,
  indexLabel,
  caption,
}: StreamgraphTableProps) {
  const t = { ...defaultStreamgraphLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const { rows, series: layers } = useMemo(() => foldStreamSeries(data, series, t.other), [data, series, t.other]);
  // The first rows render with the tab switch and the rest right after it, so opening the table stays instant.
  const { rows: shown } = useTableRows(rows, { first: 12, cap: Infinity });
  return (
    <SeriesTable
      data={shown}
      index={index}
      indexLabel={indexLabel}
      caption={caption}
      format={format}
      noData={t.empty}
      plotted={(v) => Math.max(0, v)}
      columns={layers.map((s, i) => ({ key: s.key, label: s.label, color: layerColor(s, i) }))}
      total={{ label: t.total, keys: layers.map((s) => s.key) }}
    />
  );
}

